using System.Reflection;
using System.Text;

namespace Snail.Sdk.Docs;

/// <summary>A library's public API as Markdown: each namespace, each type a reader can reach, each member with its summary.</summary>
/// <remarks>
/// The page is the same for the same assembly — no date, every list sorted — so the generated file changes in a diff only
/// when the API or its documentation did.
/// </remarks>
internal static class ApiReference
{
    private const BindingFlags Declared = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly;

    /// <summary>Writes the reference of an assembly into the output folder and answers with the path of the page.</summary>
    public static string Write(string assemblyPath, string documentationPath, IEnumerable<string> references, string outputFolder)
    {
        using var inspection = Inspection.Open(assemblyPath, references);
        var documentation = Documentation.Read(documentationPath, references);
        var name = inspection.Assembly.GetName().Name!;
        var page = Path.Combine(Directory.CreateDirectory(outputFolder).FullName, $"{name}.md");

        File.WriteAllText(page, Page(name, inspection.VisibleTypes(), documentation));

        return page;
    }

    /// <summary>The page for the types of one assembly.</summary>
    public static string Page(string assemblyName, IReadOnlyList<Type> types, Documentation documentation)
    {
        var page = new StringBuilder();

        page.AppendLine($"# {assemblyName}");
        page.AppendLine();
        page.AppendLine("The public API, generated by Snail.Sdk.Docs from the built assembly and its XML documentation. Do not edit: build with `-p:SnailReference=true`.");

        var extensions = Extensions(types);
        var declared = types.Select(Key).ToHashSet(StringComparer.Ordinal);
        var extendedElsewhere = extensions.Values.Select(group => group[0].Extended).Where(extended => !declared.Contains(Key(extended)));
        var namespaces = types
            .Concat(extendedElsewhere)
            .GroupBy(type => type.Namespace ?? string.Empty)
            .OrderBy(group => group.Key, StringComparer.Ordinal);

        foreach (var space in namespaces)
        {
            page.AppendLine();
            page.AppendLine($"## {(space.Key.Length == 0 ? "(global)" : space.Key)}");

            foreach (var type in space.OrderBy(Title, StringComparer.Ordinal))
                AppendType(page, type, documentation, extensions.GetValueOrDefault(Key(type)) ?? [], declared.Contains(Key(type)));
        }

        return page.ToString();
    }

    /// <summary>The static extension members the types declare, by the type each extends.</summary>
    /// <remarks>
    /// A static extension member is called on the type it extends — <c>JobOwners.Session(services)</c> — so it is listed
    /// under that type rather than the class whose <c>extension</c> block declares it, where a reader looking for
    /// <c>JobOwners</c> did not find it (Snail.Sdk.Mcp.Http's <c>HttpSessions</c>). A type of another assembly gets a
    /// section of its own on this page, which says where the type is.
    /// </remarks>
    private static Dictionary<string, List<(Type Extended, MemberInfo Member)>> Extensions(IReadOnlyList<Type> types)
    {
        var extensions = new Dictionary<string, List<(Type Extended, MemberInfo Member)>>(StringComparer.Ordinal);
        var members = types.SelectMany(type => type.GetMembers(Declared)).OfType<MethodInfo>().Where(IsReadable);

        foreach (var method in members)
        {
            if (ExtendedBy(method) is not { } extended)
                continue;

            if (!extensions.TryGetValue(Key(extended), out var group))
                extensions[Key(extended)] = group = [];

            group.Add((extended, method));
        }

        return extensions;
    }

    /// <summary>The type a static extension member extends, or null for any other method and for one whose types this inspection cannot resolve.</summary>
    private static Type? ExtendedBy(MethodInfo method)
    {
        try
        {
            return Names.Extended(method);
        }
        catch (FileNotFoundException)
        {
            return null;
        }
    }

    private static string Key(Type type) => $"{type.Assembly.GetName().Name}:{type.FullName ?? type.Name}";

    private static void AppendType(StringBuilder page, Type type, Documentation documentation, List<(Type Extended, MemberInfo Member)> extensions, bool isDeclared)
    {
        page.AppendLine();
        page.AppendLine($"### {Kind(type)} {Title(type)}");

        var summary = isDeclared ? documentation.Summary(Names.DocumentationId(type)) : ExtendedHere(type, extensions);

        if (summary.Length > 0)
        {
            page.AppendLine();
            page.AppendLine(summary);
        }

        var members = isDeclared ? Members(type).Where(member => member is not MethodInfo method || ExtendedBy(method) is null) : [];
        var rows = members
            .Concat(extensions.Select(extension => extension.Member))
            .Select(member => Row(member, documentation))
            .OrderBy(row => row.Signature, StringComparer.Ordinal)
            .ToList();

        if (rows.Count == 0)
            return;

        page.AppendLine();
        page.AppendLine("| Member | Summary |");
        page.AppendLine("| --- | --- |");

        foreach (var (signature, memberSummary) in rows)
            page.AppendLine($"| `{signature.Replace("|", "\\|", StringComparison.Ordinal)}` | {memberSummary} |");
    }

    /// <summary>The member's row, or its name with what was missing when a type it uses was not among the references.</summary>
    private static (string Signature, string Summary) Row(MemberInfo member, Documentation documentation)
    {
        try
        {
            return (Names.Signature(member), documentation.Summary(Names.DocumentationId(member), InheritedFrom(member)));
        }
        catch (FileNotFoundException missing)
        {
            return ($"{member.Name} (not resolved: {missing.FileName ?? missing.Message})", string.Empty);
        }
    }

    /// <summary>
    /// The ids an inheritdoc without a cref takes its text from: the same member on each base type and each interface. A
    /// documentation id names its owner and nothing else about it, so the candidates are found without resolving the
    /// member each one overrides or implements.
    /// </summary>
    private static IReadOnlyList<string> InheritedFrom(MemberInfo member)
    {
        if (member is ConstructorInfo or FieldInfo)
            return [];

        var owners = new List<Type>();

        for (var type = member.DeclaringType!.BaseType; type is not null; type = type.BaseType)
            owners.Add(type);

        owners.AddRange(member.DeclaringType!.GetInterfaces());

        return [.. owners.Select(owner => Names.DocumentationId(member, owner))];
    }

    /// <summary>What the section of a type another assembly declares says: where the type is, and which classes here extend it.</summary>
    private static string ExtendedHere(Type type, List<(Type Extended, MemberInfo Member)> extensions)
    {
        var declaring = extensions.Select(extension => $"`{Title(extension.Member.DeclaringType!)}`").Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal);

        return $"Declared in {type.Assembly.GetName().Name}; the members below are extensions this assembly adds to it, declared in {string.Join(", ", declaring)}.";
    }

    private static IEnumerable<MemberInfo> Members(Type type)
    {
        if (typeof(MulticastDelegate).FullName == type.BaseType?.FullName)
            return [];

        if (type.IsEnum)
            return type.GetFields(BindingFlags.Public | BindingFlags.Static);

        return type.GetMembers(Declared).Where(IsReadable);
    }

    private static bool IsReadable(MemberInfo member)
    {
        var visible = member switch
        {
            MethodBase method => IsReachable(method) && (method is ConstructorInfo || !method.IsSpecialName || method.Name.StartsWith("op_", StringComparison.Ordinal)),
            PropertyInfo property => property.GetAccessors(nonPublic: true).Any(IsReachable),
            EventInfo @event => @event.AddMethod is { } add && IsReachable(add),
            FieldInfo field => field.IsPublic || field.IsFamily || field.IsFamilyOrAssembly,
            _ => false
        };

        return visible && !member.Name.Contains('<', StringComparison.Ordinal) && !IsCompilerGenerated(member);
    }

    private static bool IsReachable(MethodBase method) => method.IsPublic || method.IsFamily || method.IsFamilyOrAssembly;

    private static bool IsCompilerGenerated(MemberInfo member) =>
        member.CustomAttributes.Any(attribute => attribute.AttributeType.FullName == "System.Runtime.CompilerServices.CompilerGeneratedAttribute");

    private static string Kind(Type type) => type switch
    {
        { IsEnum: true } => "enum",
        { IsInterface: true } => "interface",
        { IsValueType: true } => "struct",
        { BaseType.FullName: "System.MulticastDelegate" } => "delegate",
        { IsAbstract: true, IsSealed: true } => "static class",
        { IsAbstract: true } => "abstract class",
        _ => "class"
    };

    private static string Title(Type type)
    {
        var name = type.IsGenericTypeDefinition ? Names.Of(type) : type.Name;

        return type.IsNested ? $"{Title(type.DeclaringType!)}.{name}" : name;
    }
}
